INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'forever', 'adv.', '/fərˈevə/', '永远;永久地', 'We promised that we would stay friends forever.', '我们约定永远做朋友。', 'Friends Forever', 1, 0, 'senior', 'wordlist', 'required1', 'U4', 'friends forever', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'familiar', 'adj.', '/fəˈmɪliə/', '熟悉的;常见的', 'On my first day, a familiar face in the crowd made me feel calm.', '开学第一天,人群中一张熟悉的脸让我安心。', 'Friends Forever', 2, 0, 'senior', 'wordlist', 'required1', 'U4', 'a familiar face', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'adventure', 'n.', '/ədˈventʃə/', '历险;奇遇', 'Making new friends in a new city felt like a great adventure.', '在新城市结交朋友感觉像一场奇妙的历险。', 'Friends Forever', 3, 0, 'senior', 'wordlist', 'required1', 'U4', 'a great adventure', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'prefer', 'v.', '/prɪˈfɜː/', '更喜欢;宁愿', 'Some people prefer to make friends face to face rather than online.', '有些人更喜欢面对面交朋友而不是网上交友。', 'Friends Forever', 4, 0, 'senior', 'wordlist', 'required1', 'U4', 'prefer to', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'lose track of', 'phr.', '/ˌluːz ˈtræk əv/', '不了解……的动态;失去联系', 'Moving to a new town once meant you might lose track of your friends.', '搬到新城镇曾意味着你可能会和朋友失去联系。', 'Friends Forever', 5, 0, 'senior', 'wordlist', 'required1', 'U4', 'lose track of friends', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'deliver', 'v.', '/dɪˈlɪvə/', '递送;传送', 'Long ago, a letter from a faraway friend could take ages to deliver.', '很久以前,远方朋友的来信要很久才能送到。', 'Friends Forever', 6, 0, 'senior', 'wordlist', 'required1', 'U4', 'deliver a letter', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'thanks to', 'phr.', '/ˈθæŋks tuː/', '多亏;由于', 'Thanks to social media, we can keep in touch with friends all over the world.', '多亏了社交媒体,我们能和世界各地的朋友保持联系。', 'Friends Forever', 7, 0, 'senior', 'wordlist', 'required1', 'U4', 'thanks to technology', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'advance', 'n.', '/ədˈvɑːns/', '进步;进展', 'Advances in technology have changed the way we make friends.', '技术的进步改变了我们结交朋友的方式。', 'Friends Forever', 8, 0, 'senior', 'wordlist', 'required1', 'U4', 'advances in technology', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'significantly', 'adv.', '/sɪɡˈnɪfɪkəntli/', '显著地;重大地', 'How we communicate with friends has changed significantly in recent years.', '近年来我们与朋友交流的方式发生了显著变化。', 'Friends Forever', 9, 0, 'senior', 'wordlist', 'required1', 'U4', 'change significantly', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'social media', 'n.', '/ˌsəʊʃl ˈmiːdiə/', '社交媒体', 'Social media lets us see what our friends are up to every day.', '社交媒体让我们每天都能了解朋友的近况。', 'Friends Forever', 10, 0, 'senior', 'wordlist', 'required1', 'U4', 'use social media', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'maintain', 'v.', '/meɪnˈteɪn/', '保持;维持', 'It takes time and care to maintain a true friendship.', '维持一段真挚的友谊需要时间和用心。', 'Friends Forever', 11, 0, 'senior', 'wordlist', 'required1', 'U4', 'maintain a friendship', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'click', 'v.', '/klɪk/', '点击(鼠标)', 'You can click on a friend''s name to send a quick message.', '你可以点击朋友的名字来快速发条消息。', 'Friends Forever', 12, 0, 'senior', 'wordlist', 'required1', 'U4', 'click on a name', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'digital', 'adj.', '/ˈdɪdʒɪtl/', '数字的;数码的', 'The digital age lets us find people who share our interests.', '数字时代让我们能找到志趣相投的人。', 'Friends Forever', 13, 0, 'senior', 'wordlist', 'required1', 'U4', 'the digital age', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'enable', 'v.', '/ɪˈneɪbl/', '使能够;使可能', 'The Internet enables us to connect with friends on the other side of the world.', '互联网使我们能与地球另一端的朋友联系。', 'Friends Forever', 14, 0, 'senior', 'wordlist', 'required1', 'U4', 'enable us to', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'unusual', 'adj.', '/ʌnˈjuːʒuəl/', '不寻常的;异常的', 'Online, you can meet people who enjoy the same unusual hobby as you.', '在网上,你能遇到和你有同样冷门爱好的人。', 'Friends Forever', 15, 0, 'senior', 'wordlist', 'required1', 'U4', 'an unusual hobby', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'site', 'n.', '/saɪt/', '网站;地点', 'On many social media sites, people post only their happiest moments.', '在许多社交媒体网站上,人们只发自己最开心的时刻。', 'Friends Forever', 16, 0, 'senior', 'wordlist', 'required1', 'U4', 'a social media site', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'tend', 'v.', '/tend/', '往往;倾向于', 'People tend to post positive updates that make them seem happy.', '人们往往只发让自己显得快乐的正面动态。', 'Friends Forever', 17, 0, 'senior', 'wordlist', 'required1', 'U4', 'tend to do', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'update', 'n.', '/ˈʌpdeɪt/', '最新消息;更新', 'She shared a cheerful update about her new school online.', '她在网上分享了关于新学校的一条愉快近况。', 'Friends Forever', 18, 0, 'senior', 'wordlist', 'required1', 'U4', 'a positive update', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'saying', 'n.', '/ˈseɪɪŋ/', '格言;谚语', 'There is an old saying that a friend in need is a friend indeed.', '有句老话说,患难见真情。', 'Friends Forever', 19, 0, 'senior', 'wordlist', 'required1', 'U4', 'an old saying', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'criminal', 'n.', '/ˈkrɪmɪnl/', '罪犯', 'Online, you should be careful, as a stranger could even be a criminal.', '在网上要小心,因为陌生人甚至可能是罪犯。', 'Friends Forever', 20, 0, 'senior', 'wordlist', 'required1', 'U4', 'a dangerous criminal', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'acquire', 'v.', '/əˈkwaɪə/', '获得;得到', 'Technology has changed the way we acquire friends.', '科技改变了我们结交朋友的方式。', 'Friends Forever', 21, 0, 'senior', 'wordlist', 'required1', 'U4', 'acquire friends', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'goods', 'n.', '/ɡʊdz/', '好东西;财物;商品', 'As one saying goes, no one would choose to live without friends, even if he had all other goods.', '有言道,即使拥有其他一切好东西,也没有人愿意没有朋友地生活。', 'Friends Forever', 22, 0, 'senior', 'wordlist', 'required1', 'U4', 'all other goods', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'prove', 'v.', '/pruːv/', '证明;证实', 'Hard times often prove who your real friends are.', '艰难时刻常常证明谁才是你真正的朋友。', 'Friends Forever', 23, 0, 'senior', 'wordlist', 'required1', 'U4', 'prove a point', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'illustrate', 'v.', '/ˈɪləstreɪt/', '(举例)说明;阐明', 'The story is used to illustrate how strong true friendship can be.', '这个故事用来说明真挚的友谊有多坚固。', 'Friends Forever', 24, 0, 'senior', 'wordlist', 'required1', 'U4', 'illustrate an idea', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'diagram', 'n.', '/ˈdaɪəɡræm/', '图解;示意图', 'We drew a diagram to show what makes a good friendship.', '我们画了一张示意图来展示好友谊的要素。', 'Friends Forever', 25, 0, 'senior', 'wordlist', 'required1', 'U4', 'complete the diagram', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'inspiring', 'adj.', '/ɪnˈspaɪərɪŋ/', '鼓舞人心的;启发灵感的', 'Lucy is a smart girl whose ideas are always inspiring.', '露西是个聪明的女孩,她的想法总是很有启发性。', 'Friends Forever', 26, 0, 'senior', 'wordlist', 'required1', 'U4', 'inspiring ideas', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'teenager', 'n.', '/ˈtiːneɪdʒə/', '青少年;十几岁的孩子', 'We are all teenagers who love walking and making new friends.', '我们都是热爱散步、喜欢结交新朋友的青少年。', 'Friends Forever', 27, 0, 'senior', 'wordlist', 'required1', 'U4', 'a group of teenagers', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'pour', 'v.', '/pɔː/', '灌;注;倒', 'To make ''friendship soup'', pour a box of love into a pot.', '做"友谊汤",先把一盒爱倒进锅里。', 'Friends Forever', 28, 0, 'senior', 'wordlist', 'required1', 'U4', 'pour into', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'pack', 'n.', '/pæk/', '小盒;小包', 'The recipe adds one pack of similar interests to the friendship soup.', '这份食谱往友谊汤里加了一小包相似的兴趣。', 'Friends Forever', 29, 0, 'senior', 'wordlist', 'required1', 'U4', 'a pack of', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'comfort', 'n.', '/ˈkʌmfət/', '安慰;慰藉', 'A good friend offers comfort when you are feeling down.', '好朋友会在你情绪低落时给予安慰。', 'Friends Forever', 30, 0, 'senior', 'wordlist', 'required1', 'U4', 'a glass of comfort', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'patience', 'n.', '/ˈpeɪʃns/', '耐心', 'Patience is the ability to wait without becoming anxious or angry.', '耐心就是等待时不焦虑也不生气的能力。', 'Friends Forever', 31, 0, 'senior', 'wordlist', 'required1', 'U4', 'two drops of patience', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'passion', 'n.', '/ˈpæʃn/', '强烈的情感;激情', 'Their shared passion for music brought the two friends together.', '对音乐共同的热情让这两个朋友走到了一起。', 'Friends Forever', 32, 0, 'senior', 'wordlist', 'required1', 'U4', 'a bag of passion', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'generosity', 'n.', '/ˌdʒenəˈrɒsɪti/', '慷慨;大方', 'Generosity means being kind, especially by giving things to others.', '慷慨意味着善良,尤其是把东西分享给别人。', 'Friends Forever', 33, 0, 'senior', 'wordlist', 'required1', 'U4', 'an act of generosity', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'slice', 'n.', '/slaɪs/', '片;薄片', 'Add a slice of humour, and your friendship will never feel boring.', '加上一片幽默,你们的友谊就永远不会无聊。', 'Friends Forever', 34, 0, 'senior', 'wordlist', 'required1', 'U4', 'a slice of humour', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'humour', 'n.', '/ˈhjuːmə/', '幽默感', 'A friend with a good sense of humour can cheer up the whole group.', '一个有幽默感的朋友能让整个团体都开心起来。', 'Friends Forever', 35, 0, 'senior', 'wordlist', 'required1', 'U4', 'a sense of humour', '美式拼 humor', 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'quality', 'n.', '/ˈkwɒlɪti/', '素质;品质', 'Honesty is the quality that I value most in a friend.', '诚实是我在朋友身上最看重的品质。', 'Friends Forever', 36, 0, 'senior', 'wordlist', 'required1', 'U4', 'an important quality', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'anxious', 'adj.', '/ˈæŋkʃəs/', '焦虑的;不安的', 'I felt anxious before the trip, but my best friend calmed me down.', '出行前我很焦虑,但我最好的朋友让我平静了下来。', 'Friends Forever', 37, 0, 'senior', 'wordlist', 'required1', 'U4', 'feel anxious', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'distance', 'n.', '/ˈdɪstəns/', '距离;远方', 'True friendship can last across any distance.', '真挚的友谊能跨越任何距离。', 'Friends Forever', 38, 0, 'senior', 'wordlist', 'required1', 'U4', 'across a distance', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'postpone', 'v.', '/pəʊsˈpəʊn/', '推迟;使延期', 'When Matt broke his leg, his friends thought about postponing their trip.', '马特摔断腿后,他的朋友们想过推迟旅行。', 'Friends Forever', 39, 0, 'senior', 'wordlist', 'required1', 'U4', 'postpone the trip', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'ordinary', 'adj.', '/ˈɔːdnri/', '普通的;平常的', 'Even an ordinary day feels special when a good friend is around.', '有好朋友在身边,连平常的一天都觉得特别。', 'Friends Forever', 40, 0, 'senior', 'wordlist', 'required1', 'U4', 'an ordinary day', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'drag', 'v.', '/dræɡ/', '拖;拉', 'Nothing could drag him away from his old hometown and his friends.', '没有什么能把他从老家和朋友身边拉走。', 'Friends Forever', 41, 0, 'senior', 'wordlist', 'required1', 'U4', 'drag away', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'ought to', 'modal', '/ˈɔːt tuː/', '应该;应当', 'We agreed that in twenty years each of us ought to have made our fortune.', '我们约定二十年后各自都应当已经发了财。', 'Friends Forever', 42, 0, 'senior', 'wordlist', 'required1', 'U4', 'ought to do', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'correspond', 'v.', '/ˌkɒrɪˈspɒnd/', '通信', 'For a time the two friends corresponded, but later they lost touch.', '两个朋友通信了一段时间,但后来失去了联系。', 'Friends Forever', 43, 0, 'senior', 'wordlist', 'required1', 'U4', 'correspond with', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'partner', 'n.', '/ˈpɑːtnə/', '伙伴;搭档', 'He came a thousand miles, hoping his old partner would turn up.', '他奔波千里,希望老搭档会出现。', 'Friends Forever', 44, 0, 'senior', 'wordlist', 'required1', 'U4', 'an old partner', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'turn up', 'phr.', '/ˌtɜːn ˈʌp/', '(意外地)出现;露面', 'He waited at the door, hoping his friend would turn up.', '他在门口等着,希望朋友会出现。', 'Friends Forever', 45, 0, 'senior', 'wordlist', 'required1', 'U4', 'turn up on time', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'appointed', 'adj.', '/əˈpɔɪntɪd/', '约定的;指定的', 'Bob was waiting at the appointed place exactly on time.', '鲍勃准时在约定的地点等候。', 'Friends Forever', 46, 0, 'senior', 'wordlist', 'required1', 'U4', 'the appointed place', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'scene', 'n.', '/siːn/', '场景;现场', 'The two friends meeting again was a truly moving scene.', '两位朋友重逢是非常动人的一幕。', 'Friends Forever', 47, 0, 'senior', 'wordlist', 'required1', 'U4', 'a moving scene', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'personality', 'n.', '/ˌpɜːsəˈnæləti/', '个性;性格', 'Her warm personality makes it easy for her to make friends.', '她热情的性格让她很容易交到朋友。', 'Friends Forever', 48, 0, 'senior', 'wordlist', 'required1', 'U4', 'a warm personality', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'ashamed', 'adj.', '/əˈʃeɪmd/', '感到惭愧的;难为情的', 'A real friend will never make you feel ashamed of who you are.', '真正的朋友绝不会让你为真实的自己感到难为情。', 'Friends Forever', 49, 0, 'senior', 'wordlist', 'required1', 'U4', 'be ashamed of', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'location', 'n.', '/ləʊˈkeɪʃn/', '地点;位置', 'We chose a quiet location by the lake to catch up with old friends.', '我们选了湖边一个安静的地点和老朋友叙旧。', 'Friends Forever', 50, 0, 'senior', 'wordlist', 'required1', 'U4', 'a quiet location', NULL, 'fltrp');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('f1u4.01', '①who / whom(指人:主语 vs 宾语)', 'A2', 10, '外研社版必修第一册 U4 — 先行词指人、从句缺主语 → who;从句缺宾语且前面有介词 → 介词 + whom。who 不能作介词宾语,whom 不作主语。', 1, 'required1', 'U4', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'fltrp');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('f1u4.02', '②which / that(指物)', 'A2', 10, '外研社版必修第一册 U4 — 先行词指物(thing/tool/letter/gift 等)、从句缺主语或宾语 → 用 which 或 that;指物不能用 who/whom/whose 来代替。', 2, 'required1', 'U4', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'fltrp');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('f1u4.03', '③whose(所属)+ all/only/最高级后只用 that', 'A2', 10, '外研社版必修第一册 U4 — 表''……的''(所属关系)无论指人指物都用 whose;先行词被 all/every(thing)/the only/最高级修饰时,只能用 that,不用 which。', 3, 'required1', 'U4', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'fltrp');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U4' AND code='f1u4.01'), 'Lucy is the friend ____ helped me most when I felt lonely.', 'who', 'which', 'whose', 'whom', 'A', '先行词 friend 指人、从句缺主语 → who。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U4' AND code='f1u4.01'), 'I admire people ____ always keep their promises to their friends.', 'which', 'who', 'whose', 'whom', 'B', '先行词 people 指人、从句缺主语 → who。', 2, 2, 'mcq');
