INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U4' AND code='f1u4.02'), 'Comfort is something ____ a good friend always quietly offers.', 'who', 'whom', 'whose', 'that', 'D', '先行词 something 指物、从句缺宾语 → that。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U4' AND code='f1u4.03'), 'Lucy is the girl ____ ideas are always so inspiring.', 'whose', 'who', 'which', 'that', 'A', '表所属(她的 ideas)→ whose。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U4' AND code='f1u4.03'), 'I have a friend ____ kindness everyone around her admires.', 'who', 'whose', 'which', 'that', 'B', '表所属(他/她的 kindness)→ whose。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U4' AND code='f1u4.03'), 'He is the classmate ____ notes saved me before the exam.', 'who', 'which', 'whose', 'that', 'C', '表所属(他的 notes)→ whose。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U4' AND code='f1u4.03'), 'She is a writer ____ stories are all about true friendship.', 'who', 'which', 'that', 'whose', 'D', '表所属(她的 stories)→ whose。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U4' AND code='f1u4.03'), 'That is the boy ____ phone I borrowed at school yesterday.', 'whose', 'who', 'which', 'that', 'A', '表所属(他的 phone)→ whose。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U4' AND code='f1u4.03'), 'We met a teacher ____ patience slowly changed our whole class.', 'who', 'whose', 'which', 'that', 'B', '表所属(他/她的 patience)→ whose。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U4' AND code='f1u4.03'), 'I know a girl ____ warm smile can brighten any bad day.', 'who', 'which', 'whose', 'that', 'C', '表所属(她的 smile)→ whose。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U4' AND code='f1u4.03'), 'He is a partner ____ help I could never have managed without.', 'who', 'which', 'that', 'whose', 'D', '表所属(他的 help)→ whose。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U4' AND code='f1u4.03'), 'They are the neighbours ____ door is always open to us.', 'whose', 'who', 'which', 'that', 'A', '表所属(他们的 door)→ whose。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U4' AND code='f1u4.03'), 'She is the friend ____ advice I trust more than anyone''s.', 'who', 'whose', 'which', 'that', 'B', '表所属(她的 advice)→ whose。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U4' AND code='f1u4.03'), 'A real friend is the best gift ____ life can ever give you.', 'which', 'who', 'that', 'whose', 'C', '先行词被最高级 best 修饰 → 只用 that(不用 which)。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U4' AND code='f1u4.03'), 'Everything ____ he said about friendship turned out to be true.', 'which', 'who', 'whose', 'that', 'D', '先行词 everything → 只用 that。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U4' AND code='f1u4.03'), 'This is the only thing ____ really matters between true friends.', 'that', 'which', 'who', 'whose', 'A', '先行词被 the only 修饰 → 只用 that。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U4' AND code='f1u4.03'), 'Loyalty is all ____ I really ask of a good friend.', 'which', 'that', 'who', 'whose', 'B', '先行词 all → 只用 that。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U4' AND code='f1u4.03'), 'It was the kindest thing ____ anyone had ever done for me.', 'which', 'who', 'that', 'whose', 'C', '先行词被最高级 kindest 修饰 → 只用 that。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U4' AND code='f1u4.03'), 'There is nothing ____ can break a friendship built on trust.', 'which', 'who', 'whose', 'that', 'D', '先行词 nothing → 只用 that。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U4' AND code='f1u4.03'), 'It was the most useful advice ____ I had ever received from her.', 'that', 'which', 'who', 'whose', 'A', '先行词被最高级 most useful 修饰 → 只用 that。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U4' AND code='f1u4.03'), 'The only message ____ truly comforted me that night was from her.', 'which', 'that', 'who', 'whose', 'B', '先行词被 the only 修饰 → 只用 that。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U4' AND code='f1u4.03'), 'Friendship is the most precious thing ____ we can ever share.', 'which', 'who', 'that', 'whose', 'C', '先行词被最高级 most precious 修饰 → 只用 that。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U4' AND code='f1u4.03'), 'He gave me all the support ____ I needed during that hard week.', 'which', 'who', 'whose', 'that', 'D', '先行词被 all 修饰 → 只用 that。', 2, 20, 'mcq');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'Click for a Friend?', 'Not very long ago, moving to a new town often meant losing touch with your old friends. The only way to hear from faraway friends was to write letters that took ages to arrive. Thanks to advances in technology, all of this has changed. Today we can travel around the world and still stay in touch with the people we care about. Social media tools let us see what our friends are up to, and all we need is a connection. The digital age also helps us find others who share our interests, even when they live far away. But when you ''friend'' someone online, are they really your friends? It depends. If people always share honest, true information, these friendships can be real. Yet we should remember that what we see online is often not the whole truth, and a smiling photo can hide real problems.', '议论·网络交友是真是假', 147, '[{"q":"What was hard about keeping friendships in the past?","answer":"A","options":["You often lost touch after moving and letters were slow.","There were no friends to write to.","People refused to send any letters.","Technology made friendships impossible."],"explanation":"首段说搬家后常失联、写信很慢的转述。"},{"q":"According to the passage, what does the digital age make easier?","answer":"B","options":["Forgetting your old friends.","Finding others who like the same things.","Stopping all communication.","Hiding from everyone online."],"explanation":"原文 ''find others who share our interests'' 的转述。"},{"q":"What does the writer warn readers to keep in mind?","answer":"A","options":["What people show online may not be the whole story.","Online photos always tell the full truth.","Letters are faster than the Internet.","Real friends never use social media."],"explanation":"末句 ''not the whole truth… can hide real problems'' 的转述。"}]'::jsonb, '[{"word":"digital","cn":"数字的"},{"word":"social media","cn":"社交媒体"}]'::jsonb, 2, 'required1', 'U4', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'Speaking with My Hands', 'Lucy is one of my closest friends, but she has a hearing problem. When she first joined our school, she seemed lonely and shy, and at first it was really difficult to communicate with her. I did not want her to feel left out, so I decided to learn a new language — sign language. It allows me to ''speak'' with my hands. Little by little, we began to understand each other, and soon we became good friends. Lucy is a smart girl whose ideas are always inspiring. Whenever I have a problem that I cannot solve on my own, I ask her for help, because she is such a good listener. Learning sign language took time and patience, but it was worth every minute. Now I enjoy sharing the small moments of my life with her, and our friendship has taught me that kindness can cross any barrier.', '记叙·为听障朋友学手语', 149, '[{"q":"Why did the writer decide to learn sign language?","answer":"B","options":["To win a school prize.","So that she could talk with Lucy and include her.","Because the teacher ordered her to.","To show off in front of classmates."],"explanation":"原文不想让 Lucy 被冷落、想与她沟通的转述。"},{"q":"How does the writer describe Lucy?","answer":"C","options":["Unfriendly and rude.","Someone who never listens.","Clever, with ideas that inspire others.","A person who hates making friends."],"explanation":"原文 ''smart girl whose ideas are always inspiring'' + ''good listener'' 的转述。"},{"q":"What lesson did the friendship teach the writer?","answer":"D","options":["Friends should never need help.","Sign language is useless.","It is better to stay alone.","Kindness can break through any barrier."],"explanation":"末句 ''kindness can cross any barrier'' 的转述。"}]'::jsonb, '[{"word":"inspiring","cn":"鼓舞人心的"},{"word":"patience","cn":"耐心"}]'::jsonb, 2, 'required1', 'U4', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'After Twenty Years', 'Twenty years ago, two young men named Bob and Jimmy were the closest of friends in New York. They had grown up together like brothers. One night, before Bob left for the West to make his fortune, the two friends made a promise. They agreed to meet again at the very same spot exactly twenty years later, no matter where life had taken them or how far they had to travel. Years passed. For a while they wrote to each other, but in time they lost track of one another. Still, Bob never forgot. He came a thousand miles and stood waiting in the cold, dark street, sure that his old partner would turn up if he was still alive. To Bob, Jimmy had always been the truest and most loyal friend in the world. The story shows how a real friendship can survive long years and great distance.', '故事·忠诚的约定', 149, '[{"q":"What promise did Bob and Jimmy make?","answer":"A","options":["To return to the very spot two decades later.","To write a letter every single day.","To live in the West forever.","Never to speak to each other again."],"explanation":"原文约定二十年后回到同一地点相见的转述。"},{"q":"What happened to their contact over the years?","answer":"B","options":["They met every weekend.","They slowly lost touch with each other.","They became enemies at once.","They moved into the same house."],"explanation":"原文 ''in time they lost track of one another'' 的转述。"},{"q":"What does the story mainly show about friendship?","answer":"C","options":["It is easily broken by small problems.","It only works between brothers.","It can last through time and distance.","It needs daily letters to survive."],"explanation":"末句 ''survive long years and great distance'' 的转述。"}]'::jsonb, '[{"word":"fortune","cn":"财富"},{"word":"loyal","cn":"忠诚的"}]'::jsonb, 2, 'required1', 'U4', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'A Recipe for Friendship', 'Imagine you could cook a ''friendship soup''. Like any good soup, it would never fail to make you smile when you were feeling down. To get started, all you need is a box of love. Pour it into a pot and mix it with a few grams of smiles. Then you add the rest: two cups of trust, a spoon of encouragement, three spoons of helpfulness, and plenty of good conversation. Do not forget one pack of similar interests, a glass of comfort, and two drops of patience. Add a bag of passion, a piece of generosity, and finally a slice of humour. Of course, this is only a game, but each ''ingredient'' stands for a real quality that good friends share. Trust, kindness and patience are the things that turn two people into true friends. When you have all of these, your friendship will taste sweet and last a very long time.', '说明·友谊汤的品质', 153, '[{"q":"What is the ''friendship soup'' meant to stand for?","answer":"D","options":["A real cooking lesson.","A way to lose weight.","A list of foods to buy.","The good values that true friends have in common."],"explanation":"原文 ''each ingredient stands for a real quality'' 的转述。"},{"q":"Which of these is one of the ''ingredients'' in the soup?","answer":"A","options":["A spoon of encouragement.","A cup of anger.","A box of lies.","A bag of jealousy."],"explanation":"原文列出 ''a spoon of encouragement'' 等正面要素。"},{"q":"According to the writer, what will a friendship full of these qualities be like?","answer":"B","options":["Short and bitter.","Sweet and long-lasting.","Cold and empty.","Boring and useless."],"explanation":"末句 ''taste sweet and last a very long time'' 的转述。"}]'::jsonb, '[{"word":"generosity","cn":"慷慨"},{"word":"ingredient","cn":"原料"}]'::jsonb, 2, 'required1', 'U4', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'Bringing Matt Along', 'Andy, Clara and Matt had planned an exciting trip to London together. Then, just a few days before they were due to leave, Matt called with bad news: he had broken his leg and could not come. Andy and Clara first thought about postponing the whole trip, but Matt told them not to change their plans because of him. The two friends still wanted Matt to feel part of the adventure, so they tried to think of a clever idea. They thought about sending him postcards from every place they visited, but those might take days to arrive. In the end, they decided to print a life-size photo of Matt on a cardboard cutout and carry it everywhere they went. They took funny pictures with it at every spot. It felt as if Matt were really there with them, and later he laughed happily at all the photos.', '记叙·为生病的朋友想办法', 148, '[{"q":"Why couldn''t Matt go on the trip?","answer":"C","options":["He had lost his ticket.","He did not like London.","A broken leg kept him at home.","He was too busy at school."],"explanation":"原文 ''he had broken his leg and could not come'' 的转述(改写,非照抄)。"},{"q":"What was the problem with sending Matt postcards?","answer":"D","options":["They were too expensive.","Matt could not read.","There were no postcards for sale.","They might take days to reach him."],"explanation":"原文 ''those might take days to arrive'' 的转述。"},{"q":"What did Andy and Clara finally do to include Matt?","answer":"A","options":["They carried a cardboard photo of him and took pictures.","They cancelled the trip completely.","They forgot about him.","They phoned him every hour."],"explanation":"原文做纸板人像、随身带着拍照的转述。"}]'::jsonb, '[{"word":"postpone","cn":"推迟"},{"word":"cardboard cutout","cn":"纸板人像"}]'::jsonb, 2, 'required1', 'U4', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'Walk and Talk', 'Are you new in town and hoping to make some friends? Then Walk and Talk may be just right for you. It is a free walking group that meets every Sunday morning in the park. We are a group of friendly teenagers who love being outdoors and meeting new people. You do not need any special skills — just a pair of comfortable shoes and a smile. Every week we choose a different path, walk together for an hour or two, and chat about anything from school to films. Walking side by side makes it easy to talk, and many lasting friendships have begun on our Sunday walks. The next walk that is open to new members will be on the second Sunday of the month. You may also bring along a friend, though anyone you bring should be over twelve years old. Come and join the fun — your next good friend may be waiting on the path!', '应用·兴趣相投的散步社团', 159, '[{"q":"Who is the Walk and Talk group mainly for?","answer":"B","options":["Professional athletes only.","Newcomers who want to make friends.","People who dislike the outdoors.","Children under five years old."],"explanation":"原文面向新来、想交朋友的人的转述。"},{"q":"What does a person need in order to join?","answer":"C","options":["Special walking skills.","A lot of money.","Comfortable shoes and a friendly attitude.","Their own car."],"explanation":"原文 ''just a pair of comfortable shoes and a smile'' 的转述。"},{"q":"What is one rule for bringing a friend along?","answer":"D","options":["The friend must be a teacher.","You can bring as many babies as you like.","Friends are not allowed at all.","Anyone you bring has to be older than twelve."],"explanation":"原文 ''anyone you bring should be over twelve years old'' 的转述。"}]'::jsonb, '[{"word":"path","cn":"小径"},{"word":"outdoors","cn":"在户外"}]'::jsonb, 2, 'required1', 'U4', 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required1', 'U4', 'A New Friend on My First Day', 'When I walked into my new (1)____ on the first day, I felt nervous and completely alone. I knew no one, and everyone else already seemed to have a (2)____. Then a girl who (3)____ beside me turned and gave me a warm smile. She was the first person (4)____ really spoke to me that day. She kindly (5)____ me where everything was and introduced me to her own group. Bit by bit, my fear began to (6)____ away. By lunchtime I no longer felt like a (7)____. One small act of (8)____ had changed my whole day. Now she is one of my (9)____ friends, and I always try to be warm to anyone who looks (10)____, just as she once was to me.', 125, 2, '[{"q":"1","answer":"A","options":["classroom","kitchen","hospital","station"],"explanation":"走进新班级 classroom。"},{"q":"2","answer":"B","options":["problem","friend","holiday","price"],"explanation":"别人似乎都有 friend。"},{"q":"3","answer":"C","options":["ate","slept","sat","sang"],"explanation":"坐在我旁边 sat。"},{"q":"4","answer":"D","options":["which","whose","whom","who"],"explanation":"先行词 person 指人作主语 → who。"},{"q":"5","answer":"A","options":["showed","threw","sold","lost"],"explanation":"告诉我哪里是什么 showed。"},{"q":"6","answer":"B","options":["return","fade","increase","appear"],"explanation":"恐惧慢慢消退 fade away。"},{"q":"7","answer":"C","options":["teacher","winner","stranger","doctor"],"explanation":"不再像个陌生人 stranger。"},{"q":"8","answer":"D","options":["anger","traffic","weather","kindness"],"explanation":"一个善举 act of kindness。"},{"q":"9","answer":"A","options":["closest","tallest","fastest","richest"],"explanation":"最亲密的朋友之一 closest。"},{"q":"10","answer":"B","options":["rich","lost","busy","late"],"explanation":"看起来无助/迷茫 lost。"}]'::jsonb, 1, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required1', 'U4', 'Staying in Touch', 'My best friend Mia (1)____ to another city last summer, and I was afraid we would slowly (2)____ touch. At first I felt sad every time I passed the (3)____ where we used to play together. But the Internet has made (4)____ much less of a problem. Every evening we send each other (5)____ about our day, and on weekends we have a long video (6)____. Last month she even (7)____ me a small gift by post for my birthday. The friendship (8)____ we built years ago is still going strong. I have learnt that true friends can stay (9)____ even when they live far apart, as long as both of them keep making the (10)____.', 116, 2, '[{"q":"1","answer":"C","options":["walked","drove","moved","ran"],"explanation":"搬到另一座城市 moved。"},{"q":"2","answer":"D","options":["find","gain","win","lose"],"explanation":"失去联系 lose touch。"},{"q":"3","answer":"A","options":["park","fridge","phone","exam"],"explanation":"我们以前一起玩的公园 park。"},{"q":"4","answer":"B","options":["money","distance","homework","weather"],"explanation":"让距离不再是问题 distance。"},{"q":"5","answer":"C","options":["tickets","prices","messages","rocks"],"explanation":"互发消息 messages。"},{"q":"6","answer":"D","options":["meal","race","song","call"],"explanation":"视频通话 video call。"},{"q":"7","answer":"A","options":["sent","ate","drove","lost"],"explanation":"寄给我礼物 sent。"},{"q":"8","answer":"B","options":["who","that","whose","whom"],"explanation":"先行词 friendship 指物、从句缺宾语 → that。"},{"q":"9","answer":"C","options":["angry","silent","close","busy"],"explanation":"保持亲密 close。"},{"q":"10","answer":"D","options":["mistake","noise","mess","effort"],"explanation":"付出努力 making the effort。"}]'::jsonb, 2, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required1', 'U4', 'What Makes a Good Friend', 'Everyone has a different (1)____ of what makes a good friend. For me, the most important (2)____ is honesty. A real friend always tells you the (3)____, even when it is hard to hear. Good friends also share your (4)____ when you are happy and offer comfort when you are sad. They are patient, and they never make you feel (5)____ of who you are. Of course, no friendship is perfect, and even close friends sometimes (6)____. What really matters is that they say sorry and (7)____ things up again afterwards. A friend (8)____ stands by you in hard times is worth far more than many friends (9)____ only appear when life is easy. That, I believe, is the kind of friend everyone (10)____ have.', 125, 2, '[{"q":"1","answer":"A","options":["idea","price","road","box"],"explanation":"对……的看法 idea。"},{"q":"2","answer":"B","options":["machine","quality","ticket","building"],"explanation":"最重要的品质 quality。"},{"q":"3","answer":"C","options":["money","weather","truth","distance"],"explanation":"说出真相 the truth。"},{"q":"4","answer":"D","options":["anger","fear","debt","joy"],"explanation":"分享你的快乐 joy。"},{"q":"5","answer":"A","options":["ashamed","proud","sure","glad"],"explanation":"绝不让你为自己难为情 ashamed。"},{"q":"6","answer":"B","options":["win","quarrel","smile","agree"],"explanation":"好友偶尔也会吵架 quarrel。"},{"q":"7","answer":"C","options":["break","throw","make","lose"],"explanation":"和好 make things up。"},{"q":"8","answer":"D","options":["which","whose","whom","who"],"explanation":"先行词 friend 指人作主语 → who。"},{"q":"9","answer":"A","options":["who","which","whose","when"],"explanation":"先行词 friends 指人作主语 → who。"},{"q":"10","answer":"B","options":["was","should","does","is"],"explanation":"每个人都应该拥有 should have。"}]'::jsonb, 3, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required1', 'U4', 'Be Careful Online', 'The Internet is a wonderful (1)____ for making new friends, but we must also be careful. When you chat with a (2)____ online, you cannot always be sure who they really are. People often (3)____ only their best photos and happiest news, so the picture you see may not be the whole (4)____. As one saying goes, on the Internet nobody knows the real (5)____ behind the screen. A person who seems young could actually be (6)____; someone who sounds kind could even be a (7)____. This does not mean we should blindly (8)____ every online friend, but we should always protect ourselves. Never share your home (9)____ or other private information with people you have just met. If you stay (10)____, the Internet can still be a great place to meet friends who share your interests.', 137, 2, '[{"q":"1","answer":"C","options":["animal","season","tool","price"],"explanation":"交友的好工具 tool。"},{"q":"2","answer":"D","options":["teacher","brother","doctor","stranger"],"explanation":"和陌生人聊天 stranger。"},{"q":"3","answer":"A","options":["post","eat","drive","sleep"],"explanation":"发布最好的照片 post。"},{"q":"4","answer":"B","options":["music","truth","distance","weather"],"explanation":"未必是全部真相 the whole truth。"},{"q":"5","answer":"C","options":["price","road","person","gram"],"explanation":"屏幕后真实的人 person。"},{"q":"6","answer":"D","options":["tall","rich","busy","old"],"explanation":"看似年轻其实可能很老 old。"},{"q":"7","answer":"A","options":["criminal","teacher","friend","partner"],"explanation":"甚至可能是罪犯 criminal。"},{"q":"8","answer":"B","options":["help","trust","meet","thank"],"explanation":"不应盲目信任 trust。"},{"q":"9","answer":"C","options":["song","smile","address","joke"],"explanation":"家庭住址 home address。"},{"q":"10","answer":"D","options":["angry","late","hungry","careful"],"explanation":"保持小心 careful。"}]'::jsonb, 4, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required1', 'U4', 'Making Up After a Quarrel', 'Last week my best friend Tom and I had a silly (1)____ over a football game. We both said things (2)____ we did not really mean, and afterwards neither of us wanted to speak (3)____. For two whole days the silence between us made me feel terrible. I kept remembering all the good (4)____ we had shared and realised that our friendship was far more important than being (5)____. So I decided to take the first step. I wrote him a short (6)____ and said I was sorry. To my relief, Tom replied at once and admitted that he was (7)____ to blame too. We met in the park, talked everything (8)____, and shook hands. Now we are closer than ever. I have learnt that real friends do not (9)____ on always being right; they value the friendship more. Saying sorry first is not weak — it is one of the (10)____ things a friend can do.', 157, 2, '[{"q":"1","answer":"A","options":["quarrel","party","lesson","meal"],"explanation":"一场愚蠢的争吵 quarrel。"},{"q":"2","answer":"B","options":["who","that","whose","whom"],"explanation":"先行词 things 指物、从句缺宾语 → that。"},{"q":"3","answer":"C","options":["loudly","never","first","twice"],"explanation":"谁都不愿先开口 speak first。"},{"q":"4","answer":"D","options":["prices","rooms","rocks","times"],"explanation":"共度的美好时光 good times。"},{"q":"5","answer":"A","options":["right","late","rich","tall"],"explanation":"比争个对错更重要 being right。"},{"q":"6","answer":"B","options":["ticket","message","song","price"],"explanation":"写了一条短信息 message。"},{"q":"7","answer":"C","options":["never","hardly","partly","rarely"],"explanation":"他也有部分责任 partly to blame。"},{"q":"8","answer":"D","options":["away","off","down","over"],"explanation":"把事情谈开 talk over。"},{"q":"9","answer":"A","options":["insist","depend","rely","focus"],"explanation":"不坚持非要占理 insist on。"},{"q":"10","answer":"B","options":["slowest","bravest","heaviest","coldest"],"explanation":"最勇敢的事之一 bravest。"}]'::jsonb, 5, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required1', 'U4', 'A Surprise for a Friend', 'My friend Lily had been feeling (1)____ because she missed her old hometown. I wanted to do something to cheer her (2)____, so I decided to plan a small surprise. I quietly asked a few classmates (3)____ also knew her to help me. Together we made a colourful (4)____ full of kind messages and old photos. We chose a quiet (5)____ in the school garden and asked Lily to come after class. When she arrived and saw what we had (6)____, her eyes filled with happy tears. She said it was the nicest (7)____ anyone had ever given her. That afternoon we shared cakes, told (8)____, and laughed until the sun went down. The surprise (9)____ Lily that she was not alone in her new school. Sometimes a little (10)____ from friends is all a person needs to feel at home again.', 142, 2, '[{"q":"1","answer":"C","options":["tall","rich","down","busy"],"explanation":"情绪低落 feeling down。"},{"q":"2","answer":"D","options":["off","in","out","up"],"explanation":"让她开心起来 cheer up。"},{"q":"3","answer":"A","options":["who","which","whose","whom"],"explanation":"先行词 classmates 指人作主语 → who。"},{"q":"4","answer":"B","options":["machine","card","price","road"],"explanation":"一张彩色卡片 card。"},{"q":"5","answer":"C","options":["price","song","spot","gram"],"explanation":"安静的地点 quiet spot。"},{"q":"6","answer":"D","options":["eaten","sold","driven","done"],"explanation":"看到我们所做的 what we had done。"},{"q":"7","answer":"A","options":["surprise","mistake","noise","price"],"explanation":"最美好的惊喜 nicest surprise。"},{"q":"8","answer":"B","options":["prices","stories","rocks","bills"],"explanation":"讲故事 told stories。"},{"q":"9","answer":"C","options":["forgot","sold","reminded","lost"],"explanation":"提醒莉莉她并不孤单 reminded。"},{"q":"10","answer":"D","options":["anger","traffic","homework","kindness"],"explanation":"朋友的一点善意 kindness。"}]'::jsonb, 6, 'fltrp');
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U4 听力·对话 How Do You Make Friends?', '外研社版必修第一册 U4 · dialogue', 3, 'Tom: Hi Sophie, how do you usually make new friends?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U4 听力·短文 How Friends Once Kept in Touch', '外研社版必修第一册 U4 · passage', 2, 'Long ago, friends who lived far apart had very few ways to keep in touch.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U4 听力·对话 Planning a Surprise Party', '外研社版必修第一册 U4 · dialogue', 3, 'Ben: Emma''s birthday is next Friday. Shall we plan a surprise for her?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U4 听力·短文 How to Keep a Friendship Alive', '外研社版必修第一册 U4 · passage', 2, 'Making a friend is easy, but keeping a friendship alive takes effort from both sides.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U4 听力·对话 Helping a Worried Friend', '外研社版必修第一册 U4 · dialogue', 3, 'Lucy: You look worried, Jack. What''s wrong?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U4 听力·短文 A Friend in Need', '外研社版必修第一册 U4 · passage', 2, 'There is an old saying: a friend in need is a friend indeed.
INSERT INTO public.junior_writing_prompts (grade, topic, title_en, prompt_cn, prompt_en, requirements, min_words, max_words, sample_answer, scoring_rubric, high_sentences, error_pairs, paragraph_template, difficulty, volume, unit, publisher) VALUES (10, 'Write about a Good Friend(介绍一位好朋友)', 'My Best Friend', '假设你叫李华,学校英文报正在征集''My Best Friend''主题短文。请用英语写一篇约80词的短文,内容包括:① 简单介绍这位朋友(外貌或性格,如''a girl who is always smiling'');② 讲一件体现你们友谊的小事;③ 说说你为什么珍惜这段友谊。注意:至少用两处定语从句(who/whose/that),句子地道、围绕中心。', 'Suppose you are Li Hua. Your school English newspaper is collecting short articles on the topic ''My Best Friend''. Write a passage of about 80 words including: 1) a short introduction to your friend (looks or personality, e.g. ''a girl who is always smiling''); 2) one small thing that shows your friendship; 3) why you value this friendship. Try to use at least two attributive clauses (who / whose / that).', '["介绍朋友(My best friend is a boy/girl who … / whose …)","一件体现友谊的小事(I still remember the day … / the present that …)","为什么珍惜(She is the friend that I trust most because …)","至少两处定语从句、句子围绕中心、代词指代清楚"]'::jsonb, 70, 100, 'My best friend is a girl called Mia, who is always smiling and ready to help. She is the kind of person who never lets a friend down. I still remember the day when I felt anxious before a big test. Mia, whose words are always warm, sat beside me and said, "Don''t worry, I''m here." That small moment is something that I will never forget. She is the friend that I trust most, because true friendship, which money cannot buy, makes even ordinary days feel special.', '【15 分制】A 档(13-15):五要素齐全、组织有条理、语言准确多样;B 档(10-12):要点较全、少量错误;C 档(7-9):要点偏少、句型简单;D 档(0-6):内容不完整、错误多。', '["My best friend is a girl who is always smiling and ready to help.","She is the kind of person who never lets a friend down.","I still remember the day when I felt anxious before a big test.","She is the friend that I trust most, because true friendship makes ordinary days feel special."]'::jsonb, '[{"wrong":"She is a girl which is always smiling.","correct":"She is a girl who is always smiling.","note":"先行词指人,用 who,不用 which。"},{"wrong":"Mia, who words are warm, helped me.","correct":"Mia, whose words are warm, helped me.","note":"表所属(她的话语)用 whose,不用 who。"},{"wrong":"It is the only thing which matters.","correct":"It is the only thing that matters.","note":"先行词被 the only 修饰,只用 that,不用 which。"}]'::jsonb, '【My Best Friend 结构】
INSERT INTO public.junior_grammar_tips (grade, volume, unit, content, publisher) VALUES (10, 'required1', 'U4', '{"title":"限制性定语从句1·关系代词 who / whom / which / that / whose 速查","intro":"关系代词在定语从句里代替先行词,并在从句中作主语、宾语或定语(所属)。判断口诀:先看先行词指人还是指物,再看从句缺什么成分。本单元只学关系代词,不碰 when/where/why(那是下一单元)。","table":{"headers":["关系代词","用法 / 例句"],"rows":[["who","指人,作主语:the friend who helped me(缺主语)"],["whom","指人,作宾语(尤其介词后):the friend with whom I share secrets"],["which","指物,作主语/宾语:the gift which she gave me"],["that","指人或物,作主语/宾语:the story that touched me"],["whose","表所属''……的''(人或物):the girl whose ideas are inspiring"]]},"specialRules":[{"rule":"从句缺主语/宾语才用关系代词;指人 who/whom/that,指物 which/that","mark":"the boy who called(缺主语→who)"},{"rule":"介词后只能用 whom(指人)或 which(指物),不能用 that/who","mark":"with whom √ / with that ×"},{"rule":"表所属用 whose,人和物都行","mark":"the friend whose help I needed"},{"rule":"先行词被 all / every(thing) / the only / 最高级 修饰时,只用 that,不用 which","mark":"the only thing that matters √ / which ×"}],"why":["关系代词既''指代先行词''又在从句里''占一个成分''(主语/宾语/定语);所以判断时先定指人指物,再看从句缺的是主语、宾语还是''……的''。"],"gaokaoPoints":["who/whom/which/that/whose 的选用(看先行词指人指物 + 从句缺什么成分);语法填空、单句改错高频。","介词 + whom / which 不可用 that;the only / all / 最高级后只用 that。"],"examVsReal":[{"exam":"the friend with whom I travelled(考试/书面)","real":"the friend I travelled with","note":"口语常把介词放句末并省略关系代词"},{"exam":"the gift that she gave me(考试)","real":"the gift she gave me","note":"作宾语的关系代词口语里常省略"}]}'::jsonb, 'fltrp');
